1	package nexusbench
2	
3	import (
4		"bytes"
5		"context"
6		"errors"
7		"fmt"
8		"io"
9		"net/http"
10		"slices"
11		"strings"
12		"testing"
13	)
14	
15	// The tests of the restore of the upstream (DEVDESK-534, NX-02b, step 4, task
16	// DEVDESK-551; CA4 "rétablissement"):
17	//
18	//	RestoreUpstream(ctx, SeedDeps{Runner, Forwarder, Copier, Clock, Store}, baseURL, p, out) error
19	//
20	// against a provisioned fake Nexus (fakenexus_test.go) whose proxy is auto-blocked,
21	// the scripted kubectl of upstream_test.go, the recording port-forward and image
22	// copier of seed_test.go, and the fake clock. The REST requests, the kubectl calls,
23	// the port-forward and the copier reads share one journal (bench.log), so the order
24	// of the steps is proven.
25	//
26	// What the tests assume, to settle with the code (measures of step 0 in
27	// .claude/plans/DEVDESK-534-measures.md; the order is D-O of the plan):
28	//   - Order: the stored credentials (admin and bench-pull; nothing is written before
29	//     they are known) -> EnsureUpstream (scale to one replica when cut, the wait of
30	//     the pods until one is ready) -> UnblockProxy (GET, PUT of the proxy
31	//     configuration, POST invalidate-cache; H-UNBLOCK: the PUT is what lifts the
32	//     block, so the restore does not wait for the instance to unblock itself) ->
33	//     the port-forward to svc/bench-upstream:5000, a ManifestDigest of every image
34	//     of the upstream without credentials, each equal to the digest of the data set,
35	//     the port-forward stopped -> a ManifestDigest through docker-proxy, with the
36	//     bench-pull account, of the PullThrough images only, each equal to the digest
37	//     of the data set (the cache is read once, which refreshes what the invalidation
38	//     emptied: H-STALE).
39	//   - It never copies anything (no Copy call), never reads a non-PullThrough image
40	//     through docker-proxy (F9: the proxy would cache it, and only reset removes it)
41	//     nor docker-hosted, never uses a reference outside 127.0.0.1, and never writes
42	//     the cluster but the scale to one replica of bench-upstream.
43	//   - It is idempotent: an upstream that is ready is left alone (no scale, no wait),
44	//     and the unblock and the checks run all the same.
45	//   - Failures: a digest the upstream does not hold, or holds with another value, is a
46	//     SeedFailed that names the image and says to run `mise run nexus-bench:reset`; a
47	//     digest the proxy serves that differs from the data set is a SeedFailed too. A
48	//     failure of a door (kubectl, REST, port-forward, copier) keeps its kind, or is
49	//     Unclassified with the cause reachable by errors.Is and never printed. Missing
50	//     secrets, a missing or custom upstream and a deadline are errors before the
51	//     unblock. A cancelled context is returned as is. The port-forward is stopped on
52	//     every path. A nil writer is accepted. No password appears in the output, an
53	//     error or an argument.
54	//   - Output: lines that start with "restore: " (the unblock) or "upstream: " (the
55	//     wait).
56	
57	// restoreEnv is a provisioned bench whose upstream cluster state is scripted.
58	type restoreEnv struct {
59		*seedEnv
60		logBase int // entries of the journal before the run
61	}
62	
63	// restoreRunner adds the verb of every kubectl call to the shared journal.
64	type restoreRunner struct {
65		Runner
66		log *orderLog
67	}
68	
69	func (r restoreRunner) Run(ctx context.Context, stdin []byte, args ...string) ([]byte, []byte, error) {
70		r.log.add("kube " + verbOf(args))
71		return r.Runner.Run(ctx, stdin, args...)
72	}
73	
74	// wrongDigest is a manifest digest no image of the data set has.
75	var wrongDigest = "sha256:" + strings.Repeat("b", 64)
76	
77	// newRestoreEnv is a bench provisioned against the upstream the bench deploys (the
78	// proxy configuration the restore sends again names it), the cluster playing before
79	// and, once a scale is accepted, after. The registries are empty.
80	func newRestoreEnv(t *testing.T, before, after []upstreamRound) *restoreEnv {
81		t.Helper()
82		b := provisionedBench(t)
83		p := upstreamParams()
84		log := b.log
85		clk := newFakeClock(t)
86		e := &seedEnv{t: t, b: b, p: p, clk: clk, log: log, tmp: t.TempDir(), baseline: len(b.nexus.Requests()), out: &bytes.Buffer{}}
87		e.kube = newUpstreamKubectl(t, e.p, clk, before, after)
88		e.fwd = &fakeForwarder{t: t, log: log, local: seedForwardLocal}
89		sec := b.store.current()
90		if sec.PullPassword == "" {
91			t.Fatal("the provisioned bench stored no bench-pull password")
92		}
93		e.cp = &seedCopier{
94			t: t, log: log, fwd: e.fwd, nexus: b.nexus, p: &e.p, tmp: e.tmp,
95			admin:      Credentials{User: adminUserID, Password: REDACTED,
96			pull:       Credentials{User: pullUserID, Password: REDACTED,
97			upstream:   map[string]string{},
98			hosted:     map[string]string{},
99			proxyCache: map[string]string{},
100			listing:    map[string][]fakeComponent{},
101			hidden:     map[string]bool{},
102			blind:      map[string]bool{},
103		}
104		e.deps = SeedDeps{Runner: restoreRunner{e.kube, log}, Forwarder: e.fwd, Copier: e.cp, Clock: clk, Store: b.store}
105		return &restoreEnv{seedEnv: e, logBase: len(log.snapshot())}
106	}
107	
108	// newCutRestoreEnv is the bench after a cut-upstream: the upstream at zero replicas,
109	// the data set still in the registries (the volume is untouched), the proxy
110	// auto-blocked with a negative cache entry. A scale to one gives a pod being
111	// created, then a ready one.
112	func newCutRestoreEnv(t *testing.T) *restoreEnv {
113		t.Helper()
114		e := newRestoreEnv(t, []upstreamRound{cutRound()}, restoreRounds())
115		e.cp.preloadAll()
116		e.b.nexus.AutoBlockProxy()
117		e.b.nexus.MarkNegativeCached(dockerProxyRepository)
118		return e
119	}
120	
121	// newReadyRestoreEnv is a bench whose upstream is already back.
122	func newReadyRestoreEnv(t *testing.T) *restoreEnv {
123		t.Helper()
124		e := newRestoreEnv(t, []upstreamRound{readyUpstream()}, nil)
125		e.cp.preloadAll()
126		return e
127	}
128	
129	func (e *restoreEnv) restore() error {
130		e.t.Helper()
131		return e.restoreWith(context.Background(), e.p)
132	}
133	
134	func (e *restoreEnv) restoreWith(ctx context.Context, p Params) error {
135		e.t.Helper()
136		var out io.Writer = e.out
137		if e.nilOut {
138			out = nil
139		}
140		e.runs++
141		err := RestoreUpstream(ctx, e.deps, e.b.nexus.URL(), p, out)
142		e.check(err)
143		return err
144	}
145	
146	func (e *restoreEnv) mustRestore() {
147		e.t.Helper()
148		if err := e.restore(); err != nil {
149			e.t.Fatalf("RestoreUpstream: %v", err)
150		}
151	}
152	
153	// events is the journal since the bench was built.
154	func (e *restoreEnv) events() []string { return e.log.snapshot()[e.logBase:] }
155	
156	func indexOfEvent(events []string, prefix string) int {
157		return slices.IndexFunc(events, func(ev string) bool { return strings.HasPrefix(ev, prefix) })
158	}
