256	// requireNothingTouched checks the run stopped before it did anything.
257	func (e *restoreEnv) requireNothingTouched() {
258		e.t.Helper()
259		e.requireNoProgress()
260		if len(e.kube.lines) != 0 {
261			e.t.Errorf("the cluster was called: %q", e.kube.lines)
262		}
263		if got := len(e.b.nexus.Requests()) - e.baseline; got != 0 {
264			e.t.Errorf("%d requests to Nexus: %q", got, calls(e.b.nexus.Requests()[e.baseline:]))
265		}
266	}
267	
268	// requireUpstreamDigests checks the upstream was read once per image it holds, each
269	// without credentials, and that the proxy was read for the cached images only.
270	func (e *restoreEnv) requireReads() {
271		e.t.Helper()
272		var upstream, proxy []string
273		for _, c := range e.cp.digests {
274			switch c.where {
275			case whereUpstream:
276				upstream = append(upstream, imageArg(c.ref))
277			case whereProxy:
278				proxy = append(proxy, imageArg(c.ref))
279			}
280		}
281		var wantUp, wantProxy []string
282		for _, img := range imagesIn(LocationUpstream) {
283			wantUp = append(wantUp, imageArg(upstreamImageRef(e.fwd.local, img)))
284		}
285		for _, img := range pullThrough() {
286			wantProxy = append(wantProxy, imageArg(nexusImageRef(e.p, dockerProxyRepository, img)))
287		}
288		slices.Sort(upstream)
289		slices.Sort(wantUp)
290		if !slices.Equal(upstream, wantUp) {
291			e.t.Errorf("the upstream was read at %q, want every image it holds once: %q", upstream, wantUp)
292		}
293		if !slices.Equal(proxy, wantProxy) {
294			e.t.Errorf("docker-proxy was read at %q, want the PullThrough images only: %q", proxy, wantProxy)
295		}
296	}
