347	func TestRestoreUpstreamOrderOfTheSteps(t *testing.T) {
348		e := newCutRestoreEnv(t)
349		e.mustRestore()
350		ev := e.events()
351	
352		scale := indexOfEvent(ev, "kube scale")
353		put, post := slices.Index(ev, proxyPut), slices.Index(ev, proxyPost)
354		forward, stop := slices.Index(ev, "forward"), slices.Index(ev, "stop")
355		firstUp, lastUp := indexOfEvent(ev, "digest upstream"), lastIndexOfEvent(ev, "digest upstream")
356		firstProxy := indexOfEvent(ev, "digest proxy")
357		lastKube := lastIndexOfEvent(ev, "kube ")
358		for name, i := range map[string]int{
359			"kube scale": scale, "PUT proxy": put, "POST invalidate-cache": post, "forward": forward, "stop": stop,
360			"digest upstream": firstUp, "digest proxy": firstProxy, "a kubectl call": lastKube,
361		} {
362			if i < 0 {
363				t.Fatalf("no %q event in %q", name, ev)
364			}
365		}
366		steps := []struct {
367			name string
368			at   int
369		}{
370			{"the scale to one", scale},
371			{"the last kubectl read of the wait", lastKube},
372			{"the PUT of the proxy configuration", put},
373			{"the invalidation of the cache", post},
374			{"the port-forward opens", forward},
375			{"the first read of the upstream", firstUp},
376			{"the last read of the upstream", lastUp},
377			{"the port-forward stops", stop},
378			{"the first read through the proxy", firstProxy},
379		}
380		for i := 1; i < len(steps); i++ {
381			if steps[i-1].at >= steps[i].at {
382				t.Errorf("%s (event %d) does not come before %s (event %d):\n%s", steps[i-1].name, steps[i-1].at, steps[i].name, steps[i].at, strings.Join(ev, "\n"))
383			}
384		}
385		// The wait reads the pods after the scale and before the unblock.
386		if lastKube == scale {
387			t.Errorf("the pods were not read after the scale: %q", ev)
388		}
389		// The data set never goes through the port-forward twice.
390		if n := len(e.fwd.calls); n != 1 {
391			t.Errorf("%d port-forwards, want 1", n)
392		}
393		// The proxy is read only once the port-forward is closed.
394		for i, event := range ev {
395			if strings.HasPrefix(event, "digest proxy") && i < stop {
396				t.Errorf("%q comes before the port-forward is stopped", event)
397			}
398		}
399	}
