786	func TestRestoreUpstreamReturnsACancelledContextAsIs(t *testing.T) {
787		requireAsIs := func(t *testing.T, err error) {
788			t.Helper()
789			if !errors.Is(err, context.Canceled) {
790				t.Fatalf("err = %v, want context.Canceled", err)
791			}
792			var be *BenchError
793			if errors.As(err, &be) {
794				t.Errorf("a cancelled context is a BenchError (%v), want it as is", be)
795			}
796		}
797		t.Run("cancelled before the start: nothing is called", func(t *testing.T) {
798			e := newCutRestoreEnv(t)
799			ctx, cancel := context.WithCancel(context.Background())
800			cancel()
801			requireAsIs(t, e.restoreWith(ctx, e.p))
802			e.requireNothingTouched()
803		})
804		t.Run("cancelled during the wait for the pod: the proxy is not touched", func(t *testing.T) {
805			e := newRestoreEnv(t, []upstreamRound{cutRound()}, []upstreamRound{roundOf(1, creatingPod())})
806			e.cp.preloadAll()
807			e.b.nexus.AutoBlockProxy()
808			ctx, cancel := context.WithCancel(context.Background())
809			defer cancel()
810			e.clk.onSleep = func(n int) {
811				if n == 2 {
812					cancel()
813				}
814			}
815			requireAsIs(t, e.restoreWith(ctx, e.p))
816			e.requireOneScale("1")
817			if !e.b.nexus.ProxyBlocked() {
818				t.Error("the proxy was put back in service although the run was cancelled before the upstream was ready")
819			}
820			e.requireNoProgress()
821		})
822		t.Run("cancelled during the reads of the upstream: the port-forward is stopped", func(t *testing.T) {
823			e := newCutRestoreEnv(t)
824			ctx, cancel := context.WithCancel(context.Background())
825			defer cancel()
826			e.cp.digestErr = func(c digestCall) error {
827				if c.where == whereUpstream {
828					cancel()
829					return &BenchError{Kind: Unclassified, Cause: "skopeo inspect was interrupted", Check: "run the command again", Err: context.Canceled}
830				}
831				return nil
832			}
833			requireAsIs(t, e.restoreWith(ctx, e.p))
834			if e.fwd.stops != 1 {
835				t.Errorf("the port-forward was stopped %d times, want once", e.fwd.stops)
836			}
837			for _, c := range e.cp.digests {
838				if c.where == whereProxy {
839					t.Errorf("docker-proxy was read after the cancellation: %s", imageArg(c.ref))
840				}
841			}
842		})
843		t.Run("cancelled during the reads through the proxy", func(t *testing.T) {
844			e := newCutRestoreEnv(t)
845			ctx, cancel := context.WithCancel(context.Background())
846			defer cancel()
847			e.cp.digestErr = func(c digestCall) error {
