850					return &BenchError{Kind: Unclassified, Cause: "skopeo inspect was interrupted", Check: "run the command again", Err: context.Canceled}
851				}
852				return nil
853			}
854			requireAsIs(t, e.restoreWith(ctx, e.p))
855		})
856	}
