98	func benchLabels() map[string]string {
99		return map[string]string{
100			"app.kubernetes.io/name":       upstreamName,
101			"app.kubernetes.io/managed-by": managedByValue,
102			"app.kubernetes.io/part-of":    managedByValue,
103		}
104	}
105	
106	func presentClaim() claimState {
107		return claimState{exists: true, labels: benchLabels(), phase: "Bound", stuckReads: 2}
108	}
