247	// recycleEnv is one run: a cluster, a clock, an output.
248	type recycleEnv struct {
249		*upstreamEnv
250		k *recycleKubectl
251	}
252	
253	// recycleParams are the parameters of a run: the wait for the claim has a bound of
254	// its own, shorter than the one of the pods, so a test sees which one the code used.
255	func recycleParams() Params {
256		p := upstreamParams()
257		p.DeleteTimeout = 30 * time.Second
258		return p
259	}
260	
261	// restoreRounds are the rounds after the scale to 1: a pod being created, then ready.
262	func restoreRounds() []upstreamRound {
263		return []upstreamRound{roundOf(1, creatingPod()), roundOf(1, readyPod())}
264	}
265	
266	// newRecycleEnv is a ready upstream, a labelled claim that disappears two reads after
267	// its delete, and rounds after each scale that need one sleep to see the pod leave
268	// and one to see the new pod ready.
269	func newRecycleEnv(t *testing.T, p Params) *recycleEnv {
270		t.Helper()
271		e := &recycleEnv{upstreamEnv: newUpstreamEnv(t, p, []upstreamRound{roundOf(1, readyPod())}, nil)}
272		e.k = &recycleKubectl{
273			upstreamKubectl: e.kube,
274			afterCut:        []upstreamRound{goingRound(goingPod(upstreamPodName)), cutRound()},
275			afterRestore:    restoreRounds(),
276			claim:           presentClaim(),
277			scaleFailsFor:   "none",
278		}
279		return e
280	}
281	
282	func (e *recycleEnv) recycle(ctx context.Context) error {
283		e.t.Helper()
284		return recycleUpstreamStorage(ctx, e.k, e.clk, e.p, &e.out)
285	}
286	
287	// requireOps checks the writes the run made, in order.
288	func (e *recycleEnv) requireOps(want ...string) {
289		e.t.Helper()
290		if !slices.Equal(e.k.ops, want) {
291			e.t.Errorf("writes = %q, want %q", e.k.ops, want)
292		}
293	}
294	
295	// requireNoOp fails when the run made a write that starts with prefix.
296	func (e *recycleEnv) requireNoOp(prefix string) {
297		e.t.Helper()
298		for _, op := range e.k.ops {
299			if strings.HasPrefix(op, prefix) {
300				e.t.Errorf("writes = %q, want none that starts with %q", e.k.ops, prefix)
301				return
302			}
303		}
304	}
305	
306	// requireTouchesOnlyTheUpstream checks everything written: no Nexus, no nexus-data,
307	// no namespace, no pod, no rollout, no exec, and nothing but the four verbs.
308	func (e *recycleEnv) requireTouchesOnlyTheUpstream() {
309		e.t.Helper()
310		for _, w := range e.kube.writes {
311			verb := strings.Fields(w)[0]
312			if !slices.Contains([]string{"scale", "delete", "apply"}, verb) {
313				e.t.Errorf("write %q: the verbs of the recycling are scale, delete and apply", w)
314			}
315			for _, banned := range []string{"nexus-data", "deployment/nexus ", "namespace", "rollout", "pod", "exec"} {
316				if strings.Contains(w, banned) {
317					e.t.Errorf("write %q contains %q: the recycling touches the upstream and its claim only", w, banned)
318				}
319			}
320		}
321		for _, l := range e.kube.lines {
322			if strings.Contains(l, "nexus-data") {
323				e.t.Errorf("call %q names the claim of Nexus", l)
324			}
325		}
326	}
