11	func RestoreUpstream(ctx context.Context, d SeedDeps, baseURL string, p Params, out io.Writer) error {
12		if out == nil {
13			out = io.Discard
14		}
15		if err := ctx.Err(); err != nil {
16			return err
17		}
18		if !p.UpstreamIsBench() {
19			return customUpstreamError(p)
20		}
21		admin, pull, c, err := seedCredentials(ctx, d.Store, baseURL)
22		if err != nil {
23			return err
24		}
25		defer c.closeIdle()
26		if err := EnsureUpstream(ctx, d.Runner, d.Clock, p, out); err != nil {
27			return err
28		}
29		if err := UnblockProxy(ctx, d.Store, baseURL, p, out); err != nil {
30			return err
31		}
32		s := &seeder{ctx: ctx, d: d, p: p, out: out, c: c, baseURL: baseURL, admin: admin, pull: pull, images: Dataset()}
33		if err := s.verifyUpstream(); err != nil {
34			return err
35		}
36		return s.verifyProxy()
37	}
