39	func (s *seeder) verifyUpstream() error {
40		local, stop, err := s.d.Forwarder.Forward(s.ctx, s.p.Namespace, upstreamServiceName, upstreamServicePort)
41		if err != nil {
42			return s.failure(err, "the port-forward to the upstream")
43		}
44		if stop != nil {
45			defer func() { _ = stop() }()
46		}
47		if !strings.HasPrefix(local, seedLoopbackHost+":") || !loopbackRegistry(local) {
48			return &BenchError{Kind: SeedFailed, Cause: "the port-forward to the upstream is not on 127.0.0.1", Check: "check the kubectl on PATH, mise"}
49		}
50		for _, img := range s.images {
51			if img.Location != LocationUpstream {
52				continue
53			}
54			name := img.Name + ":" + img.Tag
55			have, err := s.d.Copier.ManifestDigest(s.ctx, upstreamImageRef(local, img), nil)
56			if errors.Is(err, errImageAbsent) {
57				return &BenchError{Kind: SeedFailed, Cause: "the upstream lost " + name, Check: resetCheck}
58			}
59			if err != nil {
60				return s.failure(err, "reading "+name+" in the upstream")
61			}
62			if have != img.Digest {
63				return &BenchError{Kind: SeedFailed, Cause: "the upstream holds another content for " + name, Check: resetCheck}
64			}
65		}
66		return nil
67	}
68	
69	func (s *seeder) verifyProxy() error {
70		for _, img := range s.images {
71			if !img.PullThrough {
72				continue
73			}
74			name := img.Name + ":" + img.Tag
75			have, err := s.d.Copier.ManifestDigest(s.ctx, nexusImageRef(s.p, dockerProxyRepository, img), &s.pull)
76			if err != nil {
77				return s.failure(err, "reading "+name+" through "+dockerProxyRepository)
78			}
79			if have != img.Digest {
80				return &BenchError{Kind: SeedFailed, Cause: dockerProxyRepository + " serves another content for " + name, Check: resetCheck}
81			}
82		}
83		return nil
84	}
85	
86	func recycleUpstreamStorage(ctx context.Context, r Runner, clk Clock, p Params, out io.Writer) error {
87		if out == nil {
88			out = io.Discard
89		}
90		if err := CutUpstream(ctx, r, clk, p, out); err != nil {
91			return err
92		}
93		d := &deployer{pf: preflight{r: r, p: p}, w: upstreamWorkload(), tag: "upstream", clk: clk, out: out}
94		ns := p.Namespace
95		get := []string{"get", "pvc", upstreamClaim, "-n", ns, "-o", "json"}
96		var claim struct {
97			Metadata struct {
98				Labels map[string]string `json:"labels"`
99			} `json:"metadata"`
100		}
101		found, err := d.fetch(ctx, "read the claim "+upstreamClaim, get, &claim, true)
102		if err != nil {
103			return err
104		}
105		if found {
106			if claim.Metadata.Labels[managedByLabel] != managedByValue {
107				return &BenchError{Kind: Unclassified, Cause: fmt.Sprintf("the claim %s does not carry the label %s=%s, so the bench did not create it", upstreamClaim, managedByLabel, managedByValue),
108					Check: d.pf.command("get", "pvc", upstreamClaim, "-n", ns, "--show-labels")}
109			}
110			args := []string{"delete", "pvc", upstreamClaim, "-n", ns, "--wait=false", applyTimeout}
111			_, errOut, err := r.Run(ctx, nil, args...)
112			if err != nil {
113				if cerr := ctx.Err(); cerr != nil {
114					return cerr
115				}
116				return d.pf.failure("delete the claim "+upstreamClaim, args, string(errOut), err)
117			}
118			deadline := clk.Now().Add(p.DeleteTimeout)
119			for {
120				found, err := d.fetch(ctx, "read the claim "+upstreamClaim, get, &claim, true)
121				if err != nil {
122					return err
123				}
124				if !found {
125					break
126				}
127				if !clk.Now().Before(deadline) {
128					return &BenchError{Kind: Deadline, Cause: fmt.Sprintf("the claim %s is still terminating after %s: a finalizer (kubernetes.io/pvc-protection) may hold it", upstreamClaim, p.DeleteTimeout),
129						Check: d.pf.command("get", "pvc", upstreamClaim, "-n", ns, "-o", "yaml")}
130				}
131				if err := clk.Sleep(ctx, upstreamPollInterval); err != nil {
132					return err
133				}
134			}
135		}
136		doc, err := render(p, []string{"40-upstream-pvc.yaml.tmpl"})
137		if err != nil {
138			return err
139		}
140		if err := d.apply(ctx, "the claim "+upstreamClaim, doc); err != nil {
141			return err
142		}
143		return EnsureUpstream(ctx, r, clk, p, out)
144	}
