2	
3	import (
4		"bytes"
5		"context"
6		"errors"
7		"fmt"
8		"io"
9		"net/http"
10		"slices"
11		"strings"
12		"testing"
13	)
14	
15	// The tests of the restore of the upstream (DEVDESK-534, NX-02b, step 4, task
16	// DEVDESK-551; CA4 "rétablissement"):
17	//
18	//	RestoreUpstream(ctx, SeedDeps{Runner, Forwarder, Copier, Clock, Store}, baseURL, p, out) error
19	//
20	// against a provisioned fake Nexus (fakenexus_test.go) whose proxy is auto-blocked,
21	// the scripted kubectl of upstream_test.go, the recording port-forward and image
22	// copier of seed_test.go, and the fake clock. The REST requests, the kubectl calls,
23	// the port-forward and the copier reads share one journal (bench.log), so the order
24	// of the steps is proven.
25	//
26	// What the tests assume, to settle with the code (measures of step 0 in
27	// .claude/plans/DEVDESK-534-measures.md; the order is D-O of the plan):
28	//   - Order: the stored credentials (admin and bench-pull; nothing is written before
29	//     they are known) -> EnsureUpstream (scale to one replica when cut, the wait of
30	//     the pods until one is ready) -> UnblockProxy (GET, PUT of the proxy
31	//     configuration, POST invalidate-cache; H-UNBLOCK: the PUT is what lifts the
32	//     block, so the restore does not wait for the instance to unblock itself) ->
33	//     the port-forward to svc/bench-upstream:5000, a ManifestDigest of every image
34	//     of the upstream without credentials, each equal to the digest of the data set,
35	//     the port-forward stopped -> a ManifestDigest through docker-proxy, with the
36	//     bench-pull account, of the PullThrough images only, each equal to the digest
37	//     of the data set (the cache is read once, which refreshes what the invalidation
38	//     emptied: H-STALE).
39	//   - It never copies anything (no Copy call), never reads a non-PullThrough image
40	//     through docker-proxy (F9: the proxy would cache it, and only reset removes it)
41	//     nor docker-hosted, never uses a reference outside 127.0.0.1, and never writes
42	//     the cluster but the scale to one replica of bench-upstream.
43	//   - It is idempotent: an upstream that is ready is left alone (no scale, no wait),
44	//     and the unblock and the checks run all the same.
45	//   - Failures: a digest the upstream does not hold, or holds with another value, is a
46	//     SeedFailed that names the image and says to run `mise run nexus-bench:reset`; a
47	//     digest the proxy serves that differs from the data set is a SeedFailed too. A
48	//     failure of a door (kubectl, REST, port-forward, copier) keeps its kind, or is
49	//     Unclassified with the cause reachable by errors.Is and never printed. Missing
50	//     secrets, a missing or custom upstream and a deadline are errors before the
51	//     unblock. A cancelled context is returned as is. The port-forward is stopped on
52	//     every path. A nil writer is accepted. No password appears in the output, an
53	//     error or an argument.
54	//   - Output: lines that start with "restore: " (the unblock) or "upstream: " (the
55	//     wait).
56	
57	// restoreEnv is a provisioned bench whose upstream cluster state is scripted.
58	type restoreEnv struct {
59		*seedEnv
60		logBase int // entries of the journal before the run
61	}
62	
63	// restoreRunner adds the verb of every kubectl call to the shared journal.
64	type restoreRunner struct {
65		Runner
66		log *orderLog
67	}
