300	func TestRestoreUpstreamBringsACutUpstreamBack(t *testing.T) {
301		e := newCutRestoreEnv(t)
302		e.mustRestore()
303	
304		// The cluster: one scale to one replica, then a wait that needs one sleep (the
305		// pod is being created at the first round), and nothing else: the unblock does
306		// not wait for the instance to unblock itself (H-UNBLOCK).
307		e.requireOneScale("1")
308		if got := len(e.clk.sleeps); got != 1 {
309			t.Errorf("slept %v, want the single poll of the wait for the pod", e.clk.sleeps)
310		}
311		e.requireOnlyUpstreamScales()
312	
313		// The proxy is back in service: not blocked, nothing negative cached.
314		if e.b.nexus.ProxyBlocked() || e.b.nexus.NegativeCached(dockerProxyRepository) {
315			t.Errorf("the proxy is still blocked (%v) or negative cached (%v)", e.b.nexus.ProxyBlocked(), e.b.nexus.NegativeCached(dockerProxyRepository))
316		}
317		e.requireReads()
318		if len(e.fwd.calls) != 1 {
319			t.Errorf("%d port-forwards, want one", len(e.fwd.calls))
320		}
321		// Reading never changes what the registries hold.
322		e.requireListing(dockerProxyRepository, pullThrough())
323		if !strings.Contains(e.out.String(), "restore: ") {
324			t.Errorf("output %q has no restore: line", e.out.String())
325		}
326	}
