421	func TestRestoreUpstreamIsIdempotent(t *testing.T) {
422		t.Run("an upstream that is already ready is left alone, the checks run", func(t *testing.T) {
423			e := newReadyRestoreEnv(t)
424			e.b.nexus.AutoBlockProxy()
425			e.mustRestore()
426			if len(e.kube.writes) != 0 {
427				t.Errorf("wrote to the cluster: %q", e.kube.writes)
428			}
429			if len(e.clk.sleeps) != 0 {
430				t.Errorf("waited %v for an upstream that was ready", e.clk.sleeps)
431			}
432			if e.b.nexus.ProxyBlocked() {
433				t.Error("the proxy was not put back in service")
434			}
435			e.requireReads()
436		})
437		t.Run("an upstream that is starting is waited for without a write", func(t *testing.T) {
438			e := newRestoreEnv(t, []upstreamRound{roundOf(1, creatingPod()), roundOf(1, readyPod())}, nil)
439			e.cp.preloadAll()
440			e.mustRestore()
441			if len(e.kube.writes) != 0 {
442				t.Errorf("wrote to the cluster: %q", e.kube.writes)
443			}
444			if len(e.clk.sleeps) != 1 {
445				t.Errorf("slept %v, want the one poll of the wait", e.clk.sleeps)
446			}
447			e.requireReads()
448		})
449		t.Run("twice in a row writes once", func(t *testing.T) {
450			e := newCutRestoreEnv(t)
451			e.mustRestore()
452			first := len(e.b.nexus.Requests())
453			e.mustRestore()
454			e.requireOneScale("1")
455			if len(e.fwd.calls) != 2 {
456				t.Errorf("%d port-forwards for two runs, want one per run", len(e.fwd.calls))
457			}
458			if len(e.b.nexus.Requests()) == first {
459				t.Error("the second run did not put the proxy in service again: it is idempotent, not skipped")
460			}
461		})
462	}
