186	func (k *recycleKubectl) deleteClaim(norm []string) ([]byte, []byte, error) {
187		k.journal(norm, true)
188		k.ops = append(k.ops, "delete")
189		k.deletes = append(k.deletes, strings.Join(norm, " "))
190		var positional []string
191		waitFalse := false
192		namespace := ""
193		for i := 1; i < len(norm); i++ {
194			switch a := norm[i]; {
195			case a == "-n" || a == "--namespace":
196				i++
197				namespace = at(norm, i)
198			case a == "--wait=false":
199				waitFalse = true
200			case strings.HasPrefix(a, "-"):
201				k.t.Errorf("unscripted argument %q in %q", a, norm)
202			default:
203				positional = append(positional, a)
204			}
205		}
206		if got := strings.Join(positional, "/"); got != "pvc/"+upstreamClaim && got != "persistentvolumeclaim/"+upstreamClaim {
207			k.t.Errorf("delete targets %q, want pvc/%s: nothing else is ever deleted", got, upstreamClaim)
208			return nil, []byte("the fake refuses this delete"), errFakeExit1
209		}
210		if namespace != k.p.Namespace {
211			k.t.Errorf("delete in namespace %q, the run is about %q", namespace, k.p.Namespace)
212		}
213		if !waitFalse {
214			k.t.Errorf("delete without --wait=false: %q (the wait is the bounded one of the code, not kubectl's)", norm)
215		}
216		if k.deleteReply != nil {
217			return k.deleteReply.reply()
218		}
219		if !k.claim.exists {
220			return notFoundReply("persistentvolumeclaims \"" + upstreamClaim + "\"")
221		}
222		k.claim.terminating = true
223		return []byte("persistentvolumeclaim \"" + upstreamClaim + "\" deleted\n"), nil, nil
224	}
225	
226	func (k *recycleKubectl) applyClaim(stdin []byte, norm []string) ([]byte, []byte, error) {
227		k.journal(norm, true)
228		k.ops = append(k.ops, "apply")
229		k.applies = append(k.applies, bytes.Clone(stdin))
230		joined := strings.Join(norm, " ")
231		for _, want := range []string{"--server-side", "--field-manager=" + fieldManager, "-f -"} {
232			if !strings.Contains(joined, want) {
233				k.t.Errorf("apply %q lacks %q", joined, want)
234			}
235		}
236		if k.applyReply != nil {
237			return k.applyReply.reply()
238		}
239		if k.claim.exists {
240			k.t.Errorf("apply while the claim still exists (terminating: %v): it must be NotFound first", k.claim.terminating)
241			return nil, []byte("the fake refuses an apply over a live claim"), errFakeExit1
242		}
243		k.claim = claimState{exists: true, labels: benchLabels(), phase: "Pending"}
244		return []byte("persistentvolumeclaim/" + upstreamClaim + " serverside-applied\n"), nil, nil
245	}
246	
247	// recycleEnv is one run: a cluster, a clock, an output.
248	type recycleEnv struct {
249		*upstreamEnv
250		k *recycleKubectl
251	}
252	
253	// recycleParams are the parameters of a run: the wait for the claim has a bound of
254	// its own, shorter than the one of the pods, so a test sees which one the code used.
255	func recycleParams() Params {
256		p := upstreamParams()
257		p.DeleteTimeout = 30 * time.Second
258		return p
259	}
260	
261	// restoreRounds are the rounds after the scale to 1: a pod being created, then ready.
262	func restoreRounds() []upstreamRound {
263		return []upstreamRound{roundOf(1, creatingPod()), roundOf(1, readyPod())}
264	}
265	
266	// newRecycleEnv is a ready upstream, a labelled claim that disappears two reads after
267	// its delete, and rounds after each scale that need one sleep to see the pod leave
268	// and one to see the new pod ready.
269	func newRecycleEnv(t *testing.T, p Params) *recycleEnv {
270		t.Helper()
271		e := &recycleEnv{upstreamEnv: newUpstreamEnv(t, p, []upstreamRound{roundOf(1, readyPod())}, nil)}
272		e.k = &recycleKubectl{
273			upstreamKubectl: e.kube,
274			afterCut:        []upstreamRound{goingRound(goingPod(upstreamPodName)), cutRound()},
275			afterRestore:    restoreRounds(),
276			claim:           presentClaim(),
277			scaleFailsFor:   "none",
278		}
279		return e
280	}
281	
282	func (e *recycleEnv) recycle(ctx context.Context) error {
283		e.t.Helper()
284		return recycleUpstreamStorage(ctx, e.k, e.clk, e.p, &e.out)
285	}
286	
287	// requireOps checks the writes the run made, in order.
288	func (e *recycleEnv) requireOps(want ...string) {
289		e.t.Helper()
290		if !slices.Equal(e.k.ops, want) {
291			e.t.Errorf("writes = %q, want %q", e.k.ops, want)
292		}
293	}
294	
295	// requireNoOp fails when the run made a write that starts with prefix.
296	func (e *recycleEnv) requireNoOp(prefix string) {
297		e.t.Helper()
298		for _, op := range e.k.ops {
299			if strings.HasPrefix(op, prefix) {
300				e.t.Errorf("writes = %q, want none that starts with %q", e.k.ops, prefix)
301				return
302			}
303		}
304	}
305	
306	// requireTouchesOnlyTheUpstream checks everything written: no Nexus, no nexus-data,
307	// no namespace, no pod, no rollout, no exec, and nothing but the four verbs.
308	func (e *recycleEnv) requireTouchesOnlyTheUpstream() {
309		e.t.Helper()
310		for _, w := range e.kube.writes {
311			verb := strings.Fields(w)[0]
312			if !slices.Contains([]string{"scale", "delete", "apply"}, verb) {
313				e.t.Errorf("write %q: the verbs of the recycling are scale, delete and apply", w)
314			}
315			for _, banned := range []string{"nexus-data", "deployment/nexus ", "namespace", "rollout", "pod", "exec"} {
316				if strings.Contains(w, banned) {
317					e.t.Errorf("write %q contains %q: the recycling touches the upstream and its claim only", w, banned)
318				}
319			}
320		}
321		for _, l := range e.kube.lines {
322			if strings.Contains(l, "nexus-data") {
323				e.t.Errorf("call %q names the claim of Nexus", l)
324			}
325		}
326	}
327	
328	// requireTheClaimAlone checks the stdin of the apply is the one document of the
329	// claim of the upstream, the one the full stream of Render holds.
330	func (e *recycleEnv) requireTheClaimAlone(stdin []byte) {
331		e.t.Helper()
332		doc := string(stdin)
333		full, err := Render(e.p)
334		if err != nil {
335			e.t.Fatalf("Render: %v", err)
336		}
337		if !strings.Contains(string(full), doc) {
338			e.t.Errorf("the applied document is not a document of Render:\n%s", doc)
339		}
340		for _, line := range strings.Split(doc, "\n") {
341			if strings.TrimSpace(line) == "---" {
342				e.t.Errorf("the applied stream has several documents: %q", doc)
343			}
344		}
345		for _, want := range []string{"kind: PersistentVolumeClaim", "name: " + upstreamClaim} {
346			if !strings.Contains(doc, want) {
347				e.t.Errorf("the applied document lacks %q:\n%s", want, doc)
348			}
349		}
350		for _, banned := range []string{"kind: Deployment", "kind: Service", "kind: Namespace", "nexus-data"} {
351			if strings.Contains(doc, banned) {
352				e.t.Errorf("the applied stream contains %q: only the claim of the upstream is applied", banned)
353			}
354		}
355	}
