86	func recycleUpstreamStorage(ctx context.Context, r Runner, clk Clock, p Params, out io.Writer) error {
87		if out == nil {
88			out = io.Discard
89		}
90		if err := CutUpstream(ctx, r, clk, p, out); err != nil {
91			return err
92		}
93		d := &deployer{pf: preflight{r: r, p: p}, w: upstreamWorkload(), tag: "upstream", clk: clk, out: out}
94		ns := p.Namespace
95		get := []string{"get", "pvc", upstreamClaim, "-n", ns, "-o", "json"}
96		var claim struct {
97			Metadata struct {
98				Labels map[string]string `json:"labels"`
99			} `json:"metadata"`
100		}
101		found, err := d.fetch(ctx, "read the claim "+upstreamClaim, get, &claim, true)
102		if err != nil {
103			return err
104		}
105		if found {
106			if claim.Metadata.Labels[managedByLabel] != managedByValue {
107				return &BenchError{Kind: Unclassified, Cause: fmt.Sprintf("the claim %s does not carry the label %s=%s, so the bench did not create it", upstreamClaim, managedByLabel, managedByValue),
108					Check: d.pf.command("get", "pvc", upstreamClaim, "-n", ns, "--show-labels")}
109			}
110			args := []string{"delete", "pvc", upstreamClaim, "-n", ns, "--wait=false", applyTimeout}
111			_, errOut, err := r.Run(ctx, nil, args...)
112			if err != nil {
113				if cerr := ctx.Err(); cerr != nil {
114					return cerr
115				}
116				return d.pf.failure("delete the claim "+upstreamClaim, args, string(errOut), err)
117			}
118			deadline := clk.Now().Add(p.DeleteTimeout)
119			for {
120				found, err := d.fetch(ctx, "read the claim "+upstreamClaim, get, &claim, true)
121				if err != nil {
122					return err
123				}
124				if !found {
125					break
126				}
127				if !clk.Now().Before(deadline) {
128					return &BenchError{Kind: Deadline, Cause: fmt.Sprintf("the claim %s is still terminating after %s: a finalizer (kubernetes.io/pvc-protection) may hold it", upstreamClaim, p.DeleteTimeout),
129						Check: d.pf.command("get", "pvc", upstreamClaim, "-n", ns, "-o", "yaml")}
130				}
131				if err := clk.Sleep(ctx, upstreamPollInterval); err != nil {
132					return err
133				}
134			}
135		}
136		doc, err := render(p, []string{"40-upstream-pvc.yaml.tmpl"})
137		if err != nil {
138			return err
139		}
140		if err := d.apply(ctx, "the claim "+upstreamClaim, doc); err != nil {
141			return err
142		}
143		return EnsureUpstream(ctx, r, clk, p, out)
