// failure turns a failed kubectl call into a BenchError whose kind comes from
// the stderr. Neither the stderr nor the sub-process error reaches the message.
func (pf preflight) failure(what string, args []string, stderr string, err error) *BenchError {
	kind := classifyKubectl(stderr)
	reason := "kubectl failed"
	switch kind {
	case Forbidden:
		reason = "the API server refused the request (forbidden)"
	case ClusterUnreachable:
		reason = "the cluster did not answer"
	}
	return &BenchError{
		Kind:  kind,
		Cause: "could not " + what + ": " + reason,
		Check: pf.command(args...),
		Err:   err,
	}
	return host
}

// loopbackRegistry tells whether hostPort ("127.0.0.1:5000", "[::1]:5000") is
// one of the two loopback literals and nothing else ("localhost" is not: it
// resolves through the host's configuration). It parses the host and the
// port instead of testing a prefix, so "127.0.0.1@evil.com",
// "127.0.0.1.evil.com" and "127.0.0.1:5000@evil.com" are not the loopback.
func loopbackRegistry(hostPort string) bool {
	host := hostPort
	if h, p, err := net.SplitHostPort(hostPort); err == nil {
		if n, err := strconv.Atoi(p); err != nil || n < 1 || n > 65535 || strconv.Itoa(n) != p {
			return false
		}
		host = h
		if strings.HasPrefix(hostPort, "[") {
			return host == "::1"
		}
	} else if strings.HasPrefix(hostPort, "[") && strings.HasSuffix(hostPort, "]") {
		return hostPort == "[::1]"
	}
	return host == "127.0.0.1"
}

